{"command":"set -e
base=$(mktemp -d); home=$base/home; xdg=$base/xdg; mkdir -p "$home" "$xdg";
# no files
echo '### no config --conf'; HOME=$home XDG_CONFIG_HOME=$xdg ./executable --conf >out 2>err || rc=$?; echo rc=${rc:-0}; sed -n '1,80p' out; echo '--err'; sed -n '1,80p' err; rm -f out err; unset rc
# XDG config
mkdir -p "$xdg/cheat"; echo 'cheatpaths: []' > "$xdg/cheat/conf.yml";
echo '### xdg --conf'; HOME=$home XDG_CONFIG_HOME=$xdg ./executable --conf >out 2>err; echo rc=$?; sed -n '1,80p' out; echo '--err'; sed -n '1,80p' err; rm -f out err
# CHEAT_CONFIG_PATH existing
mkdir -p "$base/custom"; echo 'cheatpaths: []' > "$base/custom/c.yml";
echo '### env path --conf'; HOME=$home XDG_CONFIG_HOME=$xdg CHEAT_CONFIG_PATH="$base/custom/c.yml" ./executable --conf >out 2>err; echo rc=$?; sed -n '1,80p' out; echo '--err'; sed -n '1,80p' err; rm -f out err
# CHEAT_CONFIG_PATH missing
echo '### env path missing --conf'; HOME=$home XDG_CONFIG_HOME=$xdg CHEAT_CONFIG_PATH="$base/custom/missing.yml" ./executable --conf >out 2>err || rc=$?; echo rc=${rc:-0}; sed -n '1,80p' out; echo '--err'; sed -n '1,120p' err
rm -rf "$base""}

{"command":"runinit(){ echo "### $1"; shift; env "$@" ./executable --init >out 2>err; rc=$?; echo rc=$rc; grep -E 'path:|git clone' out | sed -n '1,20p'; echo '--err'; sed -n '1,40p' err; rm -f out err; }
base=$(mktemp -d); mkdir -p "$base/home" "$base/xdg" "$base/custom";
runinit 'HOME only' HOME="$base/home" XDG_CONFIG_HOME=
runinit 'XDG set' HOME="$base/home" XDG_CONFIG_HOME="$base/xdg"
runinit 'CHEAT_CONFIG_PATH custom file' HOME="$base/home" XDG_CONFIG_HOME="$base/xdg" CHEAT_CONFIG_PATH="$base/custom/myconf.yml"
runinit 'CHEAT_CONFIG_PATH relative' HOME="$base/home" XDG_CONFIG_HOME="$base/xdg" CHEAT_CONFIG_PATH="relconf.yml"
rm -rf "$base""}

{"command":"base=$(mktemp -d); mkdir -p "$base/p" "$base/project/sub" "$base/project/.cheat"; cat > "$base/conf.yml" <<EOF
---
editor: cat
pager: cat
cheatpaths:
  - name: configured
    path: $base/p
    tags: [ configured ]
EOF
echo configured > "$base/p/foo"; echo local > "$base/project/.cheat/foo";
(cd "$base/project/sub" && CHEAT_CONFIG_PATH="$base/conf.yml" /workspace/executable -d >"$base/out" 2>"$base/err"); echo rc=$?; cat "$base/out"; cat "$base/err";
(cd "$base/project/sub" && CHEAT_CONFIG_PATH="$base/conf.yml" /workspace/executable foo >"$base/out" 2>"$base/err"); echo rc=$?; cat "$base/out"; cat "$base/err";
(cd "$base/project/sub" && CHEAT_CONFIG_PATH="$base/conf.yml" /workspace/executable -a foo >"$base/out" 2>"$base/err"); echo rc=$?; cat -v "$base/out"; cat "$base/err"; rm -rf "$base""}
